import type { FlatToken } from "./types.js";

/**
 * Generates the complete CSS custom properties stylesheet.
 */
export function generateCss(
  globalTokens: FlatToken[],
  semanticTokens: FlatToken[],
  darkTokens: FlatToken[]
): string {
  const lines: string[] = [
    "/**",
    " * Frontend Platform Design Tokens",
    " * This file is generated by the token compiler. Do not edit directly.",
    " */",
    "",
    ":root {"
  ];

  lines.push("  /* --- Global Primitives --- */");
  for (const token of globalTokens) {
    const comment = token.description ? ` /* ${token.description} */` : "";
    lines.push(`  ${token.cssVar}: ${token.cssValue};${comment}`);
  }

  lines.push("");
  lines.push("  /* --- Semantic Tokens (Light Default) --- */");
  for (const token of semanticTokens) {
    const comment = token.description ? ` /* ${token.description} */` : "";
    lines.push(`  ${token.cssVar}: ${token.cssValue};${comment}`);
  }

  lines.push("}");
  lines.push("");

  lines.push('[data-theme="dark"] {');
  lines.push("  /* --- Semantic Overrides (Dark Theme) --- */");
  for (const token of darkTokens) {
    const comment = token.description ? ` /* ${token.description} */` : "";
    lines.push(`  ${token.cssVar}: ${token.cssValue};${comment}`);
  }
  lines.push("}");
  lines.push("");

  return lines.join("\n");
}

/**
 * Generates the TypeScript code providing typed access to tokens and CSS variables.
 */
export function generateTypeScript(
  globalTokens: FlatToken[],
  semanticTokens: FlatToken[]
): string {
  const allTokens = [...globalTokens, ...semanticTokens];

  const lines: string[] = [
    "/**",
    " * Frontend Platform Design Tokens - TypeScript Definition",
    " * This file is generated by the token compiler. Do not edit directly.",
    " */",
    "",
    "/** Flat dictionary of all token paths to their concrete resolved values */",
    "export const tokens = {"
  ];

  for (const token of allTokens) {
    lines.push(`  "${token.path}": ${JSON.stringify(token.resolvedValue)},`);
  }
  lines.push("} as const;");
  lines.push("");

  lines.push("/** Flat dictionary of token paths to their CSS Custom Property names */");
  lines.push("export const cssVariables = {");
  for (const token of allTokens) {
    lines.push(`  "${token.path}": "${token.cssVar}",`);
  }
  lines.push("} as const;");
  lines.push("");

  lines.push("export type TokenKey = keyof typeof tokens;");
  lines.push("export type CssVariable = (typeof cssVariables)[TokenKey];");
  lines.push('export type ThemeMode = "light" | "dark";');
  lines.push("");

  return lines.join("\n");
}

